<script setup lang="ts">import{onMounted}from 'vue';import{lab,load}from '../stores/research';import{useTask}from '../hooks/useTask';import{date}from '../utils/format';import PageHeading from '../components/common/PageHeading.vue';import ErrorNotice from '../components/common/ErrorNotice.vue';const{error,execute}=useTask();onMounted(()=>execute(load));</script><template><PageHeading index="06" title="每次核对，留下可核对的来路。" text="保存登录、研究排队、备注编辑、说明审阅和下载动作。计算结果以研究输入快照和SHA256核对。"/><ErrorNotice :message="error" @retry="execute(load)"/><div class="table-wrap"><table><thead><tr><th>记录</th><th>操作者</th><th>动作</th><th>对象</th><th>时刻</th></tr></thead><tbody><tr v-for="a in lab.audits"><td>{{a.id}}</td><td>{{a.actor}}</td><td>{{a.action}}</td><td>{{a.target}}</td><td>{{date(a.created_at)}}</td></tr></tbody></table></div></template>
